    "name": "mandel.exe.asm",
    "contents": "; MANDEL.EXE â ãã³ãã«ãã­éåãè²ä»ãã®æå­ã§æãï¼åºå®å°æ°ç¹ãå°æ°é¨ 12bitï¼\nSYS_PUTC    = 1\nSYS_SETATTR = 9                         ; è²ãå¤ããï¼åã®è²ãè¿ãï¼\nW           = 120                       ; æ¨ªã®æå­æ°\nH           = 36                        ; è¡æ°\nX0          = -9011                     ; -2.2 Ã 4096\nDX          = 109                       ; 3.2 / W Ã 4096\nY0          = -4915                     ; -1.2 Ã 4096\nDY          = 273                       ; 2.4 / H Ã 4096\nMAXI        = 32                        ; ããã ãåãã¦çºæ£ããªããã°éåã®ä¸­\n\n        .org 0x26000\nstart:\n        ADDI32 sp, sp, -32\n        STORE32_32 lr, sp, 0\n        STORE32_32 r24, sp, 4\n        STORE32_32 r25, sp, 8\n        STORE32_32 r26, sp, 12\n        STORE32_32 r27, sp, 16\n        STORE32_32 r28, sp, 20\n        STORE32_32 r29, sp, 24\n        STORE32_32 r30, sp, 28\n        ADDI32 r16, r0, 0x07            ; ä»ã®è²ãè¦ãã¦ãã\n        ADDI32 r23, r0, SYS_SETATTR\n        SYSCALL\n        STORE32_32 r16, r0, old_attr\n        ADDI32 r24, r0, 0               ; è¡\n.row:   MULI32 r26, r24, DY             ; ci\n        ADDI32 r26, r26, Y0\n        ADDI32 r25, r0, 0               ; æ¡\n.col:   MULI32 r27, r25, DX             ; cr\n        ADDI32 r27, r27, X0\n        ADDI32 r28, r0, 0               ; zr\n        ADDI32 r29, r0, 0               ; zi\n        ADDI32 r30, r0, 0               ; åæ°\n.it:    MULR32 r16, r28, r28            ; zrÂ²\n        SARI32 r16, r16, 12\n        MULR32 r17, r29, r29            ; ziÂ²\n        SARI32 r17, r17, 12\n        ADDR32 r18, r16, r17\n        CMPGEI32 p1, r18, 16385         ; |z|Â² > 4 ãªãçºæ£\n        BR32 p1, .esc\n        MULR32 r19, r28, r29            ; zi = 2Â·zrÂ·zi + ci\n        SARI32 r19, r19, 11\n        ADDR32 r29, r19, r26\n        SUBR32 r28, r16, r17            ; zr = zrÂ² â ziÂ² + cr\n        ADDR32 r28, r28, r27\n        ADDI32 r30, r30, 1\n        CMPLTI32 p1, r30, MAXI\n        BR32 p1, .it\n        ADDI32 r16, r0, ' '             ; éåã®ä¸­ã¯é»\n        ADDI32 r18, r0, 0x07\n        JMP32 .put\n.esc:   ANDI32 r17, r30, 15\n        LOAD8U_32 r16, r17, ramp\n        LOAD8U_32 r18, r17, colors\n.put:   STORE32_32 r16, r0, ch\n        ADDR32 r16, r18, r0\n        ADDI32 r23, r0, SYS_SETATTR\n        SYSCALL\n        LOAD32_32 r16, r0, ch\n        ADDI32 r23, r0, SYS_PUTC\n        SYSCALL\n        ADDI32 r25, r25, 1\n        CMPLTI32 p1, r25, W\n        BR32 p1, .col\n        LOAD32_32 r16, r0, old_attr\n        ADDI32 r23, r0, SYS_SETATTR\n        SYSCALL\n        ADDI32 r16, r0, 10\n        ADDI32 r23, r0, SYS_PUTC\n        SYSCALL\n        ADDI32 r24, r24, 1\n        CMPLTI32 p1, r24, H\n        BR32 p1, .row\n        LOAD32_32 lr, sp, 0\n        LOAD32_32 r24, sp, 4\n        LOAD32_32 r25, sp, 8\n        LOAD32_32 r26, sp, 12\n        LOAD32_32 r27, sp, 16\n        LOAD32_32 r28, sp, 20\n        LOAD32_32 r29, sp, 24\n        LOAD32_32 r30, sp, 28\n        ADDI32 sp, sp, 32\n        RET32\n\n        .align 4\nold_attr: .word 0\nch:     .word 0\nramp:   .ascii \".,:;-=+*#%@@%#*+\"\ncolors: .byte 0x01, 0x09, 0x03, 0x0B, 0x02, 0x0A, 0x0E, 0x06\n        .byte 0x0C, 0x04, 0x05, 0x0D, 0x0F, 0x07, 0x08, 0x09\n"
